var body: some View { Page("KeyCap", description: "One key, drawn three ways. It reads the theme's ink and surface roles directly and takes no tint — a key looks like a key whatever is around it. A cap says what the key *is*; where the key can be changed, that is a ShortcutRecorder instead.") { Section("Variants", description: "`hint` — the default — is bare faint text in the display cut: the `⌘F` beside an empty search field, the `⌥2` in a card's corner, an aside the eye may skip. `strong` is the same a step darker, for a hint that has to survive on a busy row. `key` alone draws the cap — a recessed, chip-cornered fill with no border, since a key is pressed *into* the surface rather than raised off it — and is what a settings page lists shortcuts in.") { Stack { Specimen("hint") { KeyCap(size: .medium, variant: .hint) { Text("⌥2") } }
Specimen("strong") { KeyCap(size: .medium, variant: .strong) { Text("⌘K") } }
Specimen("key") { KeyCap(size: .medium, variant: .key) { Text("⌘⇧T") } } } }
Section("Sizes", description: "Colours are shared across the three; only the type steps, and only at the top — `small` and `medium` set the same face, `large` goes one up. Pick the size from what the key sits beside: `small` next to body text, `medium` in a row of controls.") { Stack { Specimen("small") { KeyCap(size: .small, variant: .hint) { Text("⌘K") }
KeyCap(size: .small, variant: .strong) { Text("⌘K") }
KeyCap(size: .small, variant: .key) { Text("⌘") }
KeyCap(size: .small, variant: .key) { Text("⇧") }
KeyCap(size: .small, variant: .key) { Text("K") }
KeyCap(size: .small, variant: .key) { Text("Esc") } }
Specimen("medium") { KeyCap(size: .medium, variant: .hint) { Text("⌘K") }
KeyCap(size: .medium, variant: .strong) { Text("⌘K") }
KeyCap(size: .medium, variant: .key) { Text("⌘") }
KeyCap(size: .medium, variant: .key) { Text("⇧") }
KeyCap(size: .medium, variant: .key) { Text("K") }
KeyCap(size: .medium, variant: .key) { Text("Esc") } }
Specimen("large") { KeyCap(size: .large, variant: .hint) { Text("⌘K") }
KeyCap(size: .large, variant: .strong) { Text("⌘K") }
KeyCap(size: .large, variant: .key) { Text("⌘") }
KeyCap(size: .large, variant: .key) { Text("⇧") }
KeyCap(size: .large, variant: .key) { Text("K") }
KeyCap(size: .large, variant: .key) { Text("Esc") } } } }
Section("Chords", description: "A chord is several caps composed by the caller, which keeps the separator the caller's decision: macOS sets its modifiers flush, a cross-platform app usually wants a `+` between them. A hint sets the whole chord in one cap — `⌘⇧K` is one glyph run, not three — and the cap sits on the text baseline it is set in, so a sentence naming a shortcut does not gain a line of leading.") { Stack { Specimen("flush") { KeyCap(size: .small, variant: .key) { Text("⌘") }
KeyCap(size: .small, variant: .key) { Text("⇧") }
KeyCap(size: .small, variant: .key) { Text("K") } }
