Text("+")
KeyCap(size: .small, variant: .key) { Text("Shift") }
Text("+")
KeyCap(size: .small, variant: .key) { Text("P") } }.foregroundStyle(theme.vars.colorContentMuted) }
Specimen("as a hint") { KeyCap(size: .small, variant: .hint) { Text("⌘⇧K") } }
Specimen("in prose") { HStack(spacing: 0) { Text("Open the command palette with ")
KeyCap(size: .small, variant: .hint) { Text("⌘K") }
Text(", then type a document name.") } } } } } }
